update public.questions set statement_markdown='Calcule $\int xe^x\,dx$.' where id='40000000-0000-4000-8000-000000006200' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$e^x(x-1)+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Escolha $u=x$ e $dv=e^x dx$, logo $du=dx$ e $v=e^x$. Por partes, $\int xe^x dx=xe^x-\int e^x dx=e^x(x-1)+C$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006200';
update public.questions set statement_markdown='Para $x>0$, calcule $\int\ln x\,dx$.' where id='40000000-0000-4000-8000-000000006201' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x\ln x-x+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Use $u=\ln x$ e $dv=dx$, de modo que $du=dx/x$ e $v=x$. A fórmula dá $x\ln x-\int 1\,dx=x\ln x-x+C$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006201';
update public.questions set statement_markdown='Calcule $\int x\cos x\,dx$.' where id='40000000-0000-4000-8000-000000006202' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x\sin x+\cos x+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Tome $u=x$, $dv=\cos x\,dx$. Então $v=\sin x$. Obtemos $x\sin x-\int\sin x\,dx=x\sin x+\cos x+C$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006202';
update public.questions set statement_markdown='Calcule $\int xe^{2x}\,dx$.' where id='40000000-0000-4000-8000-000000006203' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$e^{2x}(x/2-1/4)+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Com $u=x$ e $dv=e^{2x}dx$, temos $v=e^{2x}/2$. Subtraia $\frac12\int e^{2x}dx$ de $xe^{2x}/2$, obtendo $e^{2x}(x/2-1/4)+C$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006203';
update public.questions set statement_markdown='Para $x>0$, calcule $\int x\ln x\,dx$.' where id='40000000-0000-4000-8000-000000006204' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x^2\ln x/2-x^2/4+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Escolha $u=\ln x$ e $dv=x\,dx$, com $v=x^2/2$. O termo restante é $\frac12\int x\,dx=x^2/4$, que deve ser subtraído de $x^2\ln x/2$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006204';
update public.questions set statement_markdown='Calcule $\int x^2e^x\,dx$.' where id='40000000-0000-4000-8000-000000006205' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$e^x(x^2-2x+2)+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Uma integração por partes resulta em $x^2e^x-2\int xe^x dx$. Repita por partes: $\int xe^x dx=e^x(x-1)$. Substituindo, resulta $e^x(x^2-2x+2)+C$. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006205';
update public.questions set statement_markdown='Calcule $\int e^x\sin x\,dx$.' where id='40000000-0000-4000-8000-000000006206' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$e^x(\sin x-\cos x)/2+C$', explanation_markdown='Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes. Defina $I=\int e^x\sin x dx$. Por partes, $I=e^x\sin x-\int e^x\cos x dx$. A segunda integral é $e^x\cos x+I$. Logo $2I=e^x(\sin x-\cos x)$; divida por dois. Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.' where question_id='40000000-0000-4000-8000-000000006206';
update public.questions set statement_markdown='Em um intervalo que não contém $0$ nem $-1$, calcule $\int\frac{dx}{x(x+1)}$.' where id='40000000-0000-4000-8000-000000006207' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\ln|x|-\ln|x+1|+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. Decomponha $1/[x(x+1)]=1/x-1/(x+1)$. Integre cada fração: $\ln|x|-\ln|x+1|+C$. Os módulos permitem os intervalos admissíveis. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006207';
update public.questions set statement_markdown='Para $x>2$, calcule $\int\frac{3}{(x-2)(x+1)}\,dx$.' where id='40000000-0000-4000-8000-000000006208' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\ln(x-2)-\ln(x+1)+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. Busque $A/(x-2)+B/(x+1)$. A identidade $3=A(x+1)+B(x-2)$ dá $A=1$, $B=-1$. Integre as duas parcelas; como $x>2$, os argumentos dos logaritmos são positivos. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006208';
update public.questions set statement_markdown='Para $x>0$, calcule $\int\frac{2x+3}{x(x+1)}\,dx$.' where id='40000000-0000-4000-8000-000000006209' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$3\ln x-\ln(x+1)+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. A identidade $2x+3=A(x+1)+Bx$ fornece $A=3$ e $B=-1$. Integre $3/x-1/(x+1)$ para obter $3\ln x-\ln(x+1)+C$. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006209';
update public.questions set statement_markdown='Para $x>1$, calcule $\int\frac{dx}{x^2-1}$.' where id='40000000-0000-4000-8000-000000006210' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\frac12\ln(x-1)-\frac12\ln(x+1)+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. Fatore $x^2-1=(x-1)(x+1)$. As frações têm coeficientes $1/2$ e $-1/2$. Integre $1/[2(x-1)]-1/[2(x+1)]$, conservando o fator $1/2$. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006210';
update public.questions set statement_markdown='Para $x>0$, calcule $\int\frac{dx}{x(x+1)^2}$.' where id='40000000-0000-4000-8000-000000006211' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\ln x-\ln(x+1)+1/(x+1)+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. O fator repetido exige $A/x+B/(x+1)+D/(x+1)^2$. A identidade dos numeradores dá $A=1$, $B=-1$, $D=-1$. A primitiva de $-(x+1)^{-2}$ é $+(x+1)^{-1}$. Some esse termo aos dois logaritmos. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006211';
update public.questions set statement_markdown='Para $x>0$, calcule $\int\frac{x^2+1}{x(x+1)}\,dx$.' where id='40000000-0000-4000-8000-000000006212' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x+\ln x-2\ln(x+1)+C$', explanation_markdown='Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador. Faça primeiro a divisão: $(x^2+1)/(x^2+x)=1+(1-x)/(x(x+1))$. A parte própria é $1/x-2/(x+1)$. Integrando com o termo polinomial, resulta $x+\ln x-2\ln(x+1)+C$. Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.' where question_id='40000000-0000-4000-8000-000000006212';
update public.questions set statement_markdown='Calcule $\int\sin^2x\,dx$.' where id='40000000-0000-4000-8000-000000006213' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x/2-\sin(2x)/4+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Use a identidade $\sin^2x=(1-\cos2x)/2$. A primitiva de $\cos2x$ é $\sin2x/2$; logo o segundo termo é $-\sin2x/4$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006213';
update public.questions set statement_markdown='Calcule $\int\cos^2x\,dx$.' where id='40000000-0000-4000-8000-000000006214' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x/2+\sin(2x)/4+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Escreva $\cos^2x=(1+\cos2x)/2$. Integre termo a termo, incluindo o fator da regra da cadeia: $x/2+\sin2x/4+C$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006214';
update public.questions set statement_markdown='Calcule $\int\sin^3x\,dx$.' where id='40000000-0000-4000-8000-000000006215' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$-\cos x+\cos^3x/3+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Separe $\sin x$ e use $\sin^2x=1-\cos^2x$. Com $u=\cos x$, $du=-\sin x dx$. Integre $-\int(1-u^2)du=-u+u^3/3+C$ e retorne a $x$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006215';
update public.questions set statement_markdown='Calcule $\int\cos^3x\,dx$.' where id='40000000-0000-4000-8000-000000006216' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\sin x-\sin^3x/3+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Escreva $\cos^3x=(1-\sin^2x)\cos x$. Use $u=\sin x$. A integral vira $\int(1-u^2)du=u-u^3/3+C$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006216';
update public.questions set statement_markdown='Em $(-\pi/2,\pi/2)$, calcule $\int\tan^2x\,dx$.' where id='40000000-0000-4000-8000-000000006217' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\tan x-x+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. A identidade $1+\tan^2x=\sec^2x$ fornece $\tan^2x=\sec^2x-1$. Integre as parcelas: a primitiva de $\sec^2x$ é $\tan x$, resultando $\tan x-x+C$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006217';
update public.questions set statement_markdown='Calcule $\int\sin^2x\cos^2x\,dx$.' where id='40000000-0000-4000-8000-000000006218' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x/8-\sin(4x)/32+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Use $\sin x\cos x=\sin2x/2$, depois $\sin^22x=(1-\cos4x)/2$. O integrando é $(1-\cos4x)/8$. Integre; a frequência quatro introduz mais um fator $1/4$, dando $x/8-\sin4x/32+C$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006218';
update public.questions set statement_markdown='Em $(-\pi/2,\pi/2)$, calcule $\int\sec^4x\,dx$.' where id='40000000-0000-4000-8000-000000006219' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\tan x+\tan^3x/3+C$', explanation_markdown='Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar. Separe $\sec^2x\,dx$ e substitua $u=\tan x$, usando $\sec^2x=1+\tan^2x$. Resta $\int(1+u^2)du=u+u^3/3+C$. Volte a $x$. Derive o resultado usando as mesmas identidades. Preste atenção aos fatores internos, como o $2$ em $\sin(2x)$.' where question_id='40000000-0000-4000-8000-000000006219';
update public.questions set statement_markdown='Calcule $\int_1^\infty x^{-2}\,dx$.' where id='40000000-0000-4000-8000-000000006300' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1$', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. Substitua o limite infinito por $b$ e use a primitiva $-1/x$. O valor é $\lim_{b\to\infty}(1-1/b)=1$. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006300';
update public.questions set statement_markdown='Calcule $\int_0^\infty e^{-2x}\,dx$.' where id='40000000-0000-4000-8000-000000006301' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1/2$', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. A primitiva é $-e^{-2x}/2$. Avalie entre $0$ e $b$. Como $e^{-2b}\to0$, a integral vale $1/2$. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006301';
update public.questions set statement_markdown='Qual é o comportamento de $\int_1^\infty dx/x$?' where id='40000000-0000-4000-8000-000000006302' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge para $+\infty$.', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. Em $[1,b]$, a integral é $\ln b$. Embora $1/x\to0$, $\ln b\to+\infty$; portanto a integral diverge. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006302';
update public.questions set statement_markdown='Calcule $\int_2^\infty 3x^{-2}\,dx$.' where id='40000000-0000-4000-8000-000000006303' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$3/2$', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. Use a primitiva $-3/x$ em $[2,b]$. O limite de $3/2-3/b$ é $3/2$. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006303';
update public.questions set statement_markdown='Calcule $\int_1^\infty\frac{\ln x}{x^2}\,dx$.' where id='40000000-0000-4000-8000-000000006304' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1$', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. Por partes, uma primitiva é $-(\ln x+1)/x$. Como $\ln b/b\to0$, o limite da avaliação entre $1$ e $b$ é $1$. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006304';
update public.questions set statement_markdown='Calcule $\int_{-\infty}^{\infty}\frac{dx}{1+x^2}$ no sentido usual de integral imprópria.' where id='40000000-0000-4000-8000-000000006305' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\pi$', explanation_markdown='Uma integral imprópria é definida por limite. Nunca substitua um limite infinito diretamente na primitiva. Separe em $0$: ambas as integrais laterais precisam convergir. A primitiva é $\arctan x$. Cada lado vale $\pi/2$; somando, o resultado é $\pi$. Confira se o resultado respeita a comparação com integrais de potência, especialmente o limiar $p=1$.' where question_id='40000000-0000-4000-8000-000000006305';
update public.questions set statement_markdown='Calcule $\int_0^1 x^{-1/2}\,dx$.' where id='40000000-0000-4000-8000-000000006306' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$2$', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. Use $a>0$ no lugar de zero. A primitiva é $2\sqrt{x}$. O limite de $2-2\sqrt a$ quando $a\to0^+$ é $2$. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006306';
update public.questions set statement_markdown='Qual é o comportamento de $\int_0^1 dx/x$?' where id='40000000-0000-4000-8000-000000006307' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge para $+\infty$.', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. Em $[a,1]$ a integral é $-\ln a$. Quando $a\to0^+$, $-\ln a\to+\infty$. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006307';
update public.questions set statement_markdown='Calcule $\int_0^4\frac{dx}{\sqrt{4-x}}$.' where id='40000000-0000-4000-8000-000000006308' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$4$', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. A singularidade fica no limite superior; integre até $b<4$ usando $-2\sqrt{4-x}$. A avaliação é $4-2\sqrt{4-b}$, que tende a $4$. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006308';
update public.questions set statement_markdown='Calcule $\int_0^1\ln x\,dx$.' where id='40000000-0000-4000-8000-000000006309' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$-1$', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. Uma primitiva é $x\ln x-x$. Avalie de $a>0$ até $1$. Como $a\ln a\to0$, o resultado é $-1$. Um integrando ilimitado pode ter integral finita. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006309';
update public.questions set statement_markdown='Calcule $\int_{-1}^1\frac{dx}{\sqrt{|x|}}$.' where id='40000000-0000-4000-8000-000000006310' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$4$', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. Separe no ponto singular $0$. Por simetria, cada integral lateral equivale a $\int_0^1x^{-1/2}dx$. Cada lado vale $2$; os limites existem separadamente e a soma é $4$. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006310';
update public.questions set statement_markdown='No sentido usual (não valor principal), $\int_{-1}^1dx/x$ é:' where id='40000000-0000-4000-8000-000000006311' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Divergente, pois as integrais laterais não são finitas.', explanation_markdown='Quando o integrando não está definido dentro do intervalo, separe a integral nos pontos problemáticos e calcule limites independentes. A integral de $-1$ até $-a$ tende a $-\infty$, enquanto a de $a$ até $1$ tende a $+\infty$. Não se pode cancelar infinitos. O valor principal simétrico é zero, mas a integral imprópria usual não existe. Teste os limites laterais separadamente. Uma soma só converge se todos os trechos necessários forem finitos.' where question_id='40000000-0000-4000-8000-000000006311';
update public.questions set statement_markdown='Calcule $\lim_{n\to\infty}(3n+2)/(n+5)$.' where id='40000000-0000-4000-8000-000000006400' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$3$', explanation_markdown='Para limites de sequências, exponha o comportamento dominante ou aplique uma transformação que preserve o limite. Divida numerador e denominador por $n$. A razão vira $(3+2/n)/(1+5/n)$ e tende a $3$. Confira se o valor proposto é compatível com alguns termos grandes da sequência; isso ajuda a detectar sinais e coeficientes trocados.' where question_id='40000000-0000-4000-8000-000000006400';
update public.questions set statement_markdown='Calcule $\lim_{n\to\infty}1/n^2$.' where id='40000000-0000-4000-8000-000000006401' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$0$', explanation_markdown='Para limites de sequências, exponha o comportamento dominante ou aplique uma transformação que preserve o limite. Para $n\ge1$, temos $0<1/n^2\le1/n$. Como $1/n\to0$, o confronto fornece limite zero. Confira se o valor proposto é compatível com alguns termos grandes da sequência; isso ajuda a detectar sinais e coeficientes trocados.' where question_id='40000000-0000-4000-8000-000000006401';
update public.questions set statement_markdown='Calcule $\lim_{n\to\infty}(\sqrt{n^2+n}-n)$.' where id='40000000-0000-4000-8000-000000006402' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1/2$', explanation_markdown='Para limites de sequências, exponha o comportamento dominante ou aplique uma transformação que preserve o limite. Racionalize: a diferença é $n/(\sqrt{n^2+n}+n)$. Divida por $n$, obtendo $1/(\sqrt{1+1/n}+1)\to1/2$. Confira se o valor proposto é compatível com alguns termos grandes da sequência; isso ajuda a detectar sinais e coeficientes trocados.' where question_id='40000000-0000-4000-8000-000000006402';
update public.questions set statement_markdown='Calcule $\lim_{n\to\infty}n/2^n$.' where id='40000000-0000-4000-8000-000000006403' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$0$', explanation_markdown='Para limites de sequências, exponha o comportamento dominante ou aplique uma transformação que preserve o limite. Para $a_n=n/2^n$, a razão $a_{n+1}/a_n=(n+1)/(2n)$ tende a $1/2$. A partir de algum índice, essa razão é menor que $3/4$, permitindo comparação com uma sequência geométrica que tende a zero. Confira se o valor proposto é compatível com alguns termos grandes da sequência; isso ajuda a detectar sinais e coeficientes trocados.' where question_id='40000000-0000-4000-8000-000000006403';
update public.questions set statement_markdown='Calcule $\lim_{n\to\infty}n\ln(1+2/n)$.' where id='40000000-0000-4000-8000-000000006404' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$2$', explanation_markdown='Para limites de sequências, exponha o comportamento dominante ou aplique uma transformação que preserve o limite. Escreva $n\ln(1+2/n)=2\,\ln(1+2/n)/(2/n)$. Use $\lim_{t\to0}\ln(1+t)/t=1$. O limite é $2$, não sua exponencial. Confira se o valor proposto é compatível com alguns termos grandes da sequência; isso ajuda a detectar sinais e coeficientes trocados.' where question_id='40000000-0000-4000-8000-000000006404';
update public.questions set statement_markdown='Para $n\ge1$, a sequência $a_n=1-1/n$ é:' where id='40000000-0000-4000-8000-000000006405' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Estritamente crescente e convergente para $1$.', explanation_markdown='Compare termos consecutivos para decidir monotonicidade e combine essa informação com um limite ou cota para concluir sobre convergência. A diferença $a_{n+1}-a_n=1/[n(n+1)]$ é positiva. Além disso, $a_n<1$ e $1/n\to0$, portanto o limite é $1$. Verifique o sentido da desigualdade em alguns índices iniciais e confirme que a cota vale para todo índice do domínio.' where question_id='40000000-0000-4000-8000-000000006405';
update public.questions set statement_markdown='Para $n\ge1$, a sequência $a_n=2+1/n$ é:' where id='40000000-0000-4000-8000-000000006406' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Estritamente decrescente e convergente para $2$.', explanation_markdown='Compare termos consecutivos para decidir monotonicidade e combine essa informação com um limite ou cota para concluir sobre convergência. A diferença entre termos consecutivos é $-1/[n(n+1)]<0$. A sequência é limitada inferiormente por $2$, e $1/n\to0$ fornece o limite $2$. Verifique o sentido da desigualdade em alguns índices iniciais e confirme que a cota vale para todo índice do domínio.' where question_id='40000000-0000-4000-8000-000000006406';
update public.questions set statement_markdown='Para $n\ge1$, classifique $a_n=n/(n+2)$.' where id='40000000-0000-4000-8000-000000006407' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Crescente, limitada e convergente para $1$.', explanation_markdown='Compare termos consecutivos para decidir monotonicidade e combine essa informação com um limite ou cota para concluir sobre convergência. Escreva $a_n=1-2/(n+2)$: a parcela subtraída diminui quando $n$ aumenta. Logo $a_n$ cresce e permanece abaixo de $1$. Seu limite é $1$. Verifique o sentido da desigualdade em alguns índices iniciais e confirme que a cota vale para todo índice do domínio.' where question_id='40000000-0000-4000-8000-000000006407';
update public.questions set statement_markdown='Para $n\ge1$, a sequência $a_n=\sqrt{n+1}-\sqrt n$ é:' where id='40000000-0000-4000-8000-000000006408' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Positiva, decrescente e convergente para $0$.', explanation_markdown='Compare termos consecutivos para decidir monotonicidade e combine essa informação com um limite ou cota para concluir sobre convergência. Racionalize: $a_n=1/(\sqrt{n+1}+\sqrt n)$. O denominador é positivo, cresce estritamente e tende a infinito. Portanto os termos decrescem para zero. Verifique o sentido da desigualdade em alguns índices iniciais e confirme que a cota vale para todo índice do domínio.' where question_id='40000000-0000-4000-8000-000000006408';
update public.questions set statement_markdown='Para $n\ge1$, $a_n=(1+1/n)^n$ é:' where id='40000000-0000-4000-8000-000000006409' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Crescente e convergente para $e$.', explanation_markdown='Compare termos consecutivos para decidir monotonicidade e combine essa informação com um limite ou cota para concluir sobre convergência. Considere $f(x)=x\ln(1+1/x)$. Sua derivada é $\ln(1+1/x)-1/(x+1)>0$, pois $\ln(1+t)>t/(1+t)$ para $t>0$. Assim $a_n=e^{f(n)}$ cresce. Como $f(n)\to1$, temos $a_n\to e$. Verifique o sentido da desigualdade em alguns índices iniciais e confirme que a cota vale para todo índice do domínio.' where question_id='40000000-0000-4000-8000-000000006409';
update public.questions set statement_markdown='Calcule $\sum_{n=0}^\infty(1/4)^n$.' where id='40000000-0000-4000-8000-000000006500' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$4/3$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. A razão é $1/4$, com módulo menor que um, e o primeiro termo é $1$. A soma é $1/(1-1/4)=4/3$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006500';
update public.questions set statement_markdown='Calcule $\sum_{n=1}^\infty(1/2)^n$.' where id='40000000-0000-4000-8000-000000006501' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. O primeiro termo é $1/2$ e a razão é $1/2$. Use primeiro termo dividido por $1-r$: $(1/2)/(1-1/2)=1$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006501';
update public.questions set statement_markdown='Calcule $\sum_{n=0}^\infty3(-1/2)^n$.' where id='40000000-0000-4000-8000-000000006502' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$2$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. Apesar dos sinais alternados, $|r|=1/2<1$. A soma é $3/(1+1/2)=2$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006502';
update public.questions set statement_markdown='Calcule $\sum_{n=2}^\infty(1/3)^n$.' where id='40000000-0000-4000-8000-000000006503' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1/6$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. O índice inicial faz o primeiro termo ser $1/9$. Divida por $1-1/3$: $(1/9)/(2/3)=1/6$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006503';
update public.questions set statement_markdown='Calcule $\sum_{n=0}^\infty(2^{n+1}+1)/5^n$.' where id='40000000-0000-4000-8000-000000006504' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$55/12$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. Separe em $2\sum(2/5)^n+\sum(1/5)^n$. Ambas as razões têm módulo menor que um. Some $2/(1-2/5)+1/(1-1/5)=10/3+5/4=55/12$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006504';
update public.questions set statement_markdown='Calcule $\sum_{n=1}^\infty[3(1/2)^n-2(1/4)^n]$.' where id='40000000-0000-4000-8000-000000006505' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$7/3$', explanation_markdown='Reconheça o primeiro termo e a razão constante. A fórmula de soma infinita só é válida quando o módulo da razão é menor que um. As duas séries geométricas convergem absolutamente, então podem ser subtraídas. Desde $n=1$, suas somas são $1$ e $1/3$. O resultado é $3\cdot1-2\cdot(1/3)=7/3$. Compare a soma encontrada com as primeiras somas parciais. Elas devem se aproximar do valor final.' where question_id='40000000-0000-4000-8000-000000006505';
update public.questions set statement_markdown='A série $\sum_{n=1}^\infty n/(n+1)$:' where id='40000000-0000-4000-8000-000000006506' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge, pois o termo geral tende a $1$.', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. A convergência de uma série exige que seu termo geral tenda a zero. Aqui $n/(n+1)\to1$, violando essa condição necessária. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006506';
update public.questions set statement_markdown='A série harmônica $\sum_{n=1}^\infty1/n$:' where id='40000000-0000-4000-8000-000000006507' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge, apesar de o termo geral tender a zero.', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. Agrupe os termos em blocos entre potências de dois. Cada bloco após o primeiro soma pelo menos $1/2$. Há infinitos blocos; as somas parciais crescem sem limite. Ter termo geral tendendo a zero não basta. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006507';
update public.questions set statement_markdown='A série $\sum_{n=1}^\infty1/n^{3/2}$:' where id='40000000-0000-4000-8000-000000006508' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge pelo critério das séries de potências de $n$, pois $p=3/2>1$.', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. Trata-se de uma série $\sum n^{-p}$, com $p=3/2$. O critério das séries desse tipo garante convergência quando $p>1$; não determina soma zero. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006508';
update public.questions set statement_markdown='Calcule $\sum_{n=1}^\infty1/[n(n+1)]$.' where id='40000000-0000-4000-8000-000000006509' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1$', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. Decomponha $1/[n(n+1)]=1/n-1/(n+1)$. A soma parcial é $1-1/(N+1)$; seu limite é $1$. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006509';
update public.questions set statement_markdown='Calcule $\sum_{n=1}^\infty1/[n(n+2)]$.' where id='40000000-0000-4000-8000-000000006510' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$3/4$', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. Use $1/[n(n+2)]=(1/n-1/(n+2))/2$. Após cancelar os termos, a soma parcial é $(1+1/2-1/(N+1)-1/(N+2))/2$. O limite é $3/4$. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006510';
update public.questions set statement_markdown='Calcule $\sum_{n=1}^\infty\ln[(n+1)^2/(n(n+2))]$.' where id='40000000-0000-4000-8000-000000006511' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\ln2$', explanation_markdown='Antes de escolher um teste, verifique a condição necessária: os termos da série precisam tender a zero. A soma dos logaritmos é o logaritmo do produto. Esse produto até $N$ se simplifica para $2(N+1)/(N+2)$. Quando $N\to\infty$, o produto tende a $2$, e a soma tende a $\ln2$. Diga explicitamente qual condição do teste foi usada e por que ela se aplica à série deste enunciado.' where question_id='40000000-0000-4000-8000-000000006511';
update public.questions set statement_markdown='Qual comparação prova a convergência de $\sum_{n=1}^\infty1/(n^2+1)$?' where id='40000000-0000-4000-8000-000000006600' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$0<1/(n^2+1)\le1/n^2$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. Como $n^2+1\ge n^2$, o inverso é menor ou igual a $1/n^2$. A série maior é convergente, com $p=2$; a comparação direta conclui. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006600';
update public.questions set statement_markdown='Qual comparação prova que $\sum_{n=1}^\infty1/\sqrt n$ diverge?' where id='40000000-0000-4000-8000-000000006601' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1/\sqrt n\ge1/n$ e a série harmônica diverge.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. Para $n\ge1$, $\sqrt n\le n$, então $1/\sqrt n\ge1/n$. A série menor já diverge; as somas parciais da maior também são ilimitadas. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006601';
update public.questions set statement_markdown='Ao comparar $a_n=(3n+1)/(n^3+2)$ com $b_n=1/n^2$, qual conclusão é correta?' where id='40000000-0000-4000-8000-000000006602' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$a_n/b_n\to3$; a série de $a_n$ converge.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A razão é $(3n^3+n^2)/(n^3+2)$ e tende a $3$. Esse limite é positivo e finito; as duas séries têm o mesmo comportamento. Como $\sum1/n^2$ converge, a série proposta também converge. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006602';
update public.questions set statement_markdown='Compare $a_n=1/\sqrt{n^2+3n}$ com $b_n=1/n$.' where id='40000000-0000-4000-8000-000000006603' and publication_status='draft';
update public.question_solutions set final_answer_markdown='A razão tende a $1$, e $\sum a_n$ diverge.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A razão é $n/\sqrt{n^2+3n}=1/\sqrt{1+3/n}\to1$. A comparação pelo limite com a série harmônica garante divergência, apesar de cada termo ser menor que $1/n$. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006603';
update public.questions set statement_markdown='Pelo teste da razão, $\sum_{n=1}^\infty n/3^n$:' where id='40000000-0000-4000-8000-000000006604' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge, com limite da razão $1/3$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A razão entre termos consecutivos é $(n+1)/(3n)$. Seu limite é $1/3<1$; a série converge. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006604';
update public.questions set statement_markdown='Pelo teste da razão, $\sum_{n=1}^\infty2^n/n!$:' where id='40000000-0000-4000-8000-000000006605' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge, com limite da razão $0$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. Usando $(n+1)!=(n+1)n!$, a razão é $2/(n+1)$. Ela tende a zero, menor que um, garantindo convergência. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006605';
update public.questions set statement_markdown='Pelo teste da razão, $\sum_{n=1}^\infty n!/4^n$:' where id='40000000-0000-4000-8000-000000006606' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge, pois a razão tende a $+\infty$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A razão é $(n+1)/4$. Ela ultrapassa um e tende a infinito; em particular os termos não tendem a zero. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006606';
update public.questions set statement_markdown='Para $\sum_{n=1}^\infty1/n^2$, o teste da razão:' where id='40000000-0000-4000-8000-000000006607' and publication_status='draft';
update public.question_solutions set final_answer_markdown='É inconclusivo: o limite é $1$, mas a série converge pelo critério $p>1$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A razão é $n^2/(n+1)^2\to1$. O teste da razão não decide nesse caso. Outro critério resolve: a série tem $p=2>1$, logo converge. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006607';
update public.questions set statement_markdown='Pelo teste da raiz, $\sum_{n=1}^\infty(2/5)^n$:' where id='40000000-0000-4000-8000-000000006608' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge, com limite da raiz $2/5$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A raiz de ordem $n$ do termo positivo é exatamente $2/5$. Como $2/5<1$, o teste garante convergência. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006608';
update public.questions set statement_markdown='Pelo teste da raiz, $\sum_{n=1}^\infty[(n+1)/(3n)]^n$:' where id='40000000-0000-4000-8000-000000006609' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge, com limite da raiz $1/3$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A raiz de ordem $n$ cancela a potência, deixando $(n+1)/(3n)$. Esse valor tende a $1/3<1$. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006609';
update public.questions set statement_markdown='Pelo teste da raiz, $\sum_{n=1}^\infty(2n/(n+1))^n$:' where id='40000000-0000-4000-8000-000000006610' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Diverge, com limite da raiz $2$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A raiz de ordem $n$ é $2n/(n+1)$. Seu limite é $2>1$, o que implica divergência. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006610';
update public.questions set statement_markdown='Pelo teste da raiz, $\sum_{n=1}^\infty n^3/2^n$:' where id='40000000-0000-4000-8000-000000006611' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Converge, com limite da raiz $1/2$.', explanation_markdown='Escolha o teste pelo formato do termo geral: razões e fatoriais favorecem razão; raízes em potência favorecem raiz; termos positivos comparáveis favorecem comparação. A raiz é $n^{3/n}/2$. Escreva $n^{3/n}=e^{3\ln n/n}$. Como $\ln n/n\to0$, o numerador tende a $1$. O limite é $1/2<1$. Confira se as hipóteses do teste valem, especialmente positividade para comparações e termos não nulos para razão ou raiz.' where question_id='40000000-0000-4000-8000-000000006611';
update public.questions set statement_markdown='A série $\sum_{n=1}^\infty(-1)^{n+1}/n$ é:' where id='40000000-0000-4000-8000-000000006700' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Condicionalmente convergente.', explanation_markdown='Para uma série alternada, separe o sinal de $b_n$ e verifique se $b_n$ decresce para zero antes de aplicar Leibniz. Os módulos $1/n$ decrescem para zero; o teste de Leibniz garante convergência. A série dos módulos é a harmônica e diverge. Logo a convergência é condicional. Diferencie convergência condicional de absoluta: examine também a série formada pelos módulos.' where question_id='40000000-0000-4000-8000-000000006700';
update public.questions set statement_markdown='A série $\sum_{n=1}^\infty(-1)^{n+1}/n^2$ é:' where id='40000000-0000-4000-8000-000000006701' and publication_status='draft';
update public.question_solutions set final_answer_markdown='Absolutamente convergente.', explanation_markdown='Para uma série alternada, separe o sinal de $b_n$ e verifique se $b_n$ decresce para zero antes de aplicar Leibniz. A série dos módulos é $\sum1/n^2$, convergente pois $p=2>1$. Convergência absoluta implica convergência da série com sinais. Diferencie convergência condicional de absoluta: examine também a série formada pelos módulos.' where question_id='40000000-0000-4000-8000-000000006701';
update public.questions set statement_markdown='Ao aproximar $\sum_{n=1}^\infty(-1)^{n+1}/n$ pelos primeiros dez termos, qual cota de Leibniz se obtém para o erro absoluto?' where id='40000000-0000-4000-8000-000000006702' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1/11$', explanation_markdown='Para uma série alternada, separe o sinal de $b_n$ e verifique se $b_n$ decresce para zero antes de aplicar Leibniz. Os módulos decrescem para zero, satisfazendo as hipóteses do teorema do resto. O erro é no máximo o módulo do primeiro termo omitido: $1/(10+1)=1/11$. Diferencie convergência condicional de absoluta: examine também a série formada pelos módulos.' where question_id='40000000-0000-4000-8000-000000006702';
update public.questions set statement_markdown='Qual é o menor número $N$ de termos que garante, pela cota de Leibniz, erro no máximo $0{,}01$ em $\sum_{n=1}^\infty(-1)^{n+1}/n^2$?' where id='40000000-0000-4000-8000-000000006703' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$9$', explanation_markdown='Para uma série alternada, separe o sinal de $b_n$ e verifique se $b_n$ decresce para zero antes de aplicar Leibniz. A cota é $1/(N+1)^2$. Exija $1/(N+1)^2\le1/100$. Temos $N+1\ge10$, logo $N\ge9$. Para $N=8$, a cota é $1/81>0{,}01$. Diferencie convergência condicional de absoluta: examine também a série formada pelos módulos.' where question_id='40000000-0000-4000-8000-000000006703';
update public.questions set statement_markdown='Se $S$ é a soma de $\sum_{n=1}^\infty(-1)^{n+1}/n$ e $S_{20}$ sua soma parcial, qual intervalo certificado pelo primeiro termo omitido contém $S$?' where id='40000000-0000-4000-8000-000000006704' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$[S_{20},S_{20}+1/21]$', explanation_markdown='Para uma série alternada, separe o sinal de $b_n$ e verifique se $b_n$ decresce para zero antes de aplicar Leibniz. Após um número par de termos, o próximo termo é positivo. O resto tem esse sinal. Seu módulo não supera $1/21$. Portanto $0\le S-S_{20}\le1/21$. Diferencie convergência condicional de absoluta: examine também a série formada pelos módulos.' where question_id='40000000-0000-4000-8000-000000006704';
update public.questions set statement_markdown='Qual é o raio de convergência de $\sum_{n=0}^\infty x^n/3^n$?' where id='40000000-0000-4000-8000-000000006800' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$3$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. A série é geométrica, de razão $x/3$. A condição $|x/3|<1$ equivale a $|x|<3$, logo $R=3$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006800';
update public.questions set statement_markdown='Qual é o intervalo de convergência de $\sum_{n=0}^\infty((x-2)/4)^n$?' where id='40000000-0000-4000-8000-000000006801' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$(-2,6)$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. A condição geométrica é $|x-2|<4$, isto é, $-2<x<6$. Nos extremos, os termos são $(-1)^n$ ou $1$ e não tendem a zero. Os extremos são excluídos. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006801';
update public.questions set statement_markdown='Qual é o raio de convergência de $\sum_{n=1}^\infty nx^n/2^n$?' where id='40000000-0000-4000-8000-000000006802' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$2$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. O teste da razão fornece limite $|x|/2$, pois $(n+1)/n\to1$. A condição é $|x|<2$, portanto $R=2$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006802';
update public.questions set statement_markdown='Qual é o intervalo de convergência de $\sum_{n=1}^\infty x^n/n$?' where id='40000000-0000-4000-8000-000000006803' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$[-1,1)$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. A razão fornece $R=1$. Os extremos precisam de análise separada. Em $x=1$ surge a harmônica divergente. Em $x=-1$ surge uma harmônica alternada convergente. Logo o intervalo é $[-1,1)$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006803';
update public.questions set statement_markdown='Qual é o intervalo de convergência de $\sum_{n=1}^\infty x^n/n^2$?' where id='40000000-0000-4000-8000-000000006804' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$[-1,1]$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. O raio calculado pela razão é $1$. Em ambos os extremos, os módulos formam $\sum1/n^2$, que converge. Inclua os dois extremos. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006804';
update public.questions set statement_markdown='Qual é o intervalo de convergência de $\sum_{n=1}^\infty(x-1)^n/(n2^n)$?' where id='40000000-0000-4000-8000-000000006805' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$[-1,3)$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. A razão dá $|x-1|/2<1$, logo $R=2$. Em $x=-1$ temos $\sum(-1)^n/n$, convergente; em $x=3$, a harmônica diverge. O intervalo é $[-1,3)$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006805';
update public.questions set statement_markdown='Qual é o raio de convergência de $\sum_{n=0}^\infty x^n/n!$?' where id='40000000-0000-4000-8000-000000006806' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$\infty$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. Para cada $x$ fixo, a razão dos módulos é $|x|/(n+1)$. O limite é zero para todo $x$, portanto a série converge em toda a reta e $R=\infty$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006806';
update public.questions set statement_markdown='Qual é o raio de convergência de $\sum_{n=1}^\infty n!x^n$?' where id='40000000-0000-4000-8000-000000006807' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$0$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. Se $x\ne0$, a razão dos módulos é $(n+1)|x|\to\infty$, causando divergência. Em $x=0$, todos os termos são zero. Só há convergência no centro, então $R=0$. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006807';
update public.questions set statement_markdown='Qual é o intervalo de convergência de $\sum_{n=1}^\infty(x+2)^n/(n^2 3^n)$?' where id='40000000-0000-4000-8000-000000006808' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$[-5,1]$', explanation_markdown='Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados. O centro é $-2$ e a razão fornece raio $3$, com interior $(-5,1)$. Nos extremos, os módulos são $1/n^2$ e somam uma série convergente. Ambos pertencem ao intervalo. Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.' where question_id='40000000-0000-4000-8000-000000006808';
update public.questions set statement_markdown='Qual é o polinômio de Maclaurin de grau dois de $e^x$?' where id='40000000-0000-4000-8000-000000006809' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$1+x+x^2/2$', explanation_markdown='Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem. As derivadas de $e^x$ em zero valem $1$. A fórmula $f(0)+f''(0)x+f''''(0)x^2/2!$ dá $1+x+x^2/2$. Confira o termo constante avaliando a aproximação no centro; ele deve coincidir com o valor da função nesse ponto.' where question_id='40000000-0000-4000-8000-000000006809';
update public.questions set statement_markdown='Qual é o polinômio de Maclaurin de grau três de $\sin x$?' where id='40000000-0000-4000-8000-000000006810' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$x-x^3/6$', explanation_markdown='Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem. As derivadas de ordem zero a três em zero são $0,1,0,-1$. Dividindo pelos fatoriais, resulta $x-x^3/3!=x-x^3/6$. Confira o termo constante avaliando a aproximação no centro; ele deve coincidir com o valor da função nesse ponto.' where question_id='40000000-0000-4000-8000-000000006810';
update public.questions set statement_markdown='Qual é o polinômio de Taylor de grau dois de $\ln x$ centrado em $x=1$?' where id='40000000-0000-4000-8000-000000006811' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$(x-1)-(x-1)^2/2$', explanation_markdown='Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem. No centro, $f(1)=0$, $f''(1)=1$ e $f''''(1)=-1$. Use potências de $x-1$: o polinômio é $(x-1)-(x-1)^2/2$. Confira o termo constante avaliando a aproximação no centro; ele deve coincidir com o valor da função nesse ponto.' where question_id='40000000-0000-4000-8000-000000006811';
update public.questions set statement_markdown='A aproximação $\cos(0{,}2)\approx1-(0{,}2)^2/2$ tem qual cota de erro absoluto pelo primeiro termo omitido da série de Maclaurin?' where id='40000000-0000-4000-8000-000000006812' and publication_status='draft';
update public.question_solutions set final_answer_markdown='$(0{,}2)^4/24=1/15000$', explanation_markdown='Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem. A série é $1-x^2/2!+x^4/4!-\cdots$. Para $x=0{,}2$, os módulos decrescem para zero. O resto após o termo quadrático tem módulo no máximo $(1/5)^4/24=1/15000$. Confira o termo constante avaliando a aproximação no centro; ele deve coincidir com o valor da função nesse ponto.' where question_id='40000000-0000-4000-8000-000000006812';
commit;
