insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062001', '40000000-0000-4000-8000-000000006200', 'Desenvolva a estratégia', 'Escolha $u=x$ e $dv=e^x dx$, logo $du=dx$ e $v=e^x$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006200' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
