insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062041', '40000000-0000-4000-8000-000000006204', 'Desenvolva a estratégia', 'Escolha $u=\ln x$ e $dv=x\,dx$, com $v=x^2/2$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006204' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062042', '40000000-0000-4000-8000-000000006204', 'Complete o cálculo', 'O termo restante é $\frac12\int x\,dx=x^2/4$, que deve ser subtraído de $x^2\ln x/2$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006204' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
