insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062061', '40000000-0000-4000-8000-000000006206', 'Desenvolva a estratégia', 'Defina $I=\int e^x\sin x dx$. Por partes, $I=e^x\sin x-\int e^x\cos x dx$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006206' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062062', '40000000-0000-4000-8000-000000006206', 'Complete o cálculo', 'A segunda integral é $e^x\cos x+I$. Logo $2I=e^x(\sin x-\cos x)$; divida por dois.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006206' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
