insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062070', '40000000-0000-4000-8000-000000006207', 'Escolha o método', 'Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062071', '40000000-0000-4000-8000-000000006207', 'Desenvolva a estratégia', 'Decomponha $1/[x(x+1)]=1/x-1/(x+1)$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062072', '40000000-0000-4000-8000-000000006207', 'Complete o cálculo', 'Integre cada fração: $\ln|x|-\ln|x+1|+C$. Os módulos permitem os intervalos admissíveis.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062073', '40000000-0000-4000-8000-000000006207', 'Confira o resultado', 'Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
