insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062081', '40000000-0000-4000-8000-000000006208', 'Desenvolva a estratégia', 'Busque $A/(x-2)+B/(x+1)$. A identidade $3=A(x+1)+B(x-2)$ dá $A=1$, $B=-1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006208' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
