insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062101', '40000000-0000-4000-8000-000000006210', 'Desenvolva a estratégia', 'Fatore $x^2-1=(x-1)(x+1)$. As frações têm coeficientes $1/2$ e $-1/2$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006210' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
