insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062110', '40000000-0000-4000-8000-000000006211', 'Escolha o método', 'Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062111', '40000000-0000-4000-8000-000000006211', 'Desenvolva a estratégia', 'O fator repetido exige $A/x+B/(x+1)+D/(x+1)^2$. A identidade dos numeradores dá $A=1$, $B=-1$, $D=-1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062112', '40000000-0000-4000-8000-000000006211', 'Complete o cálculo', 'A primitiva de $-(x+1)^{-2}$ é $+(x+1)^{-1}$. Some esse termo aos dois logaritmos.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
