insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062120', '40000000-0000-4000-8000-000000006212', 'Escolha o método', 'Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062121', '40000000-0000-4000-8000-000000006212', 'Desenvolva a estratégia', 'Faça primeiro a divisão: $(x^2+1)/(x^2+x)=1+(1-x)/(x(x+1))$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062122', '40000000-0000-4000-8000-000000006212', 'Complete o cálculo', 'A parte própria é $1/x-2/(x+1)$. Integrando com o termo polinomial, resulta $x+\ln x-2\ln(x+1)+C$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
