insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062130', '40000000-0000-4000-8000-000000006213', 'Escolha o método', 'Use identidades trigonométricas para criar uma derivada presente no integrando ou reduzir as potências antes de integrar.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006213' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062131', '40000000-0000-4000-8000-000000006213', 'Desenvolva a estratégia', 'Use a identidade $\sin^2x=(1-\cos2x)/2$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006213' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062132', '40000000-0000-4000-8000-000000006213', 'Complete o cálculo', 'A primitiva de $\cos2x$ é $\sin2x/2$; logo o segundo termo é $-\sin2x/4$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006213' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
