insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062142', '40000000-0000-4000-8000-000000006214', 'Complete o cálculo', 'Integre termo a termo, incluindo o fator da regra da cadeia: $x/2+\sin2x/4+C$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006214' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
