insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000064091', '40000000-0000-4000-8000-000000006409', 'Desenvolva a estratégia', 'Considere $f(x)=x\ln(1+1/x)$. Sua derivada é $\ln(1+1/x)-1/(x+1)>0$, pois $\ln(1+t)>t/(1+t)$ para $t>0$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006409' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000064092', '40000000-0000-4000-8000-000000006409', 'Complete o cálculo', 'Assim $a_n=e^{f(n)}$ cresce. Como $f(n)\to1$, temos $a_n\to e$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006409' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
